<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!events_schema_ready())redirect('upgrade-events.php');$u=user();$s=db()->prepare("SELECT e.*,(SELECT COUNT(*) FROM event_attendees a WHERE a.event_id=e.id AND a.attendee_status<>'cancelled') attendee_count FROM events e WHERE e.owner_user_id=? ORDER BY e.starts_at DESC");$s->execute([$u['id']]);$events=$s->fetchAll();app_header('My Events');?>
<section class="dashboard-hero"><p class="eyebrow">EVENT MANAGEMENT</p><h1>My Events</h1><p><a class="button primary" href="create.php">Create Event</a> <a class="button ghost" href="index.php">Public Schedule</a></p></section><section class="dashboard-grid"><?php foreach($events as $event):?><article class="app-card"><span class="status-badge status-<?=e($event['status'])?>"><?=e(ucfirst($event['status']))?></span><h2><?=e($event['title'])?></h2><p><?=e(event_date_label($event))?></p><p><?=(int)$event['attendee_count']?> registrations</p><p><a class="button primary" href="manage.php?id=<?=$event['id']?>">Manage</a><?php if($event['status']==='approved'):?> <a class="button ghost" href="view.php?slug=<?=urlencode($event['slug'])?>">View</a><?php endif?></p></article><?php endforeach?><?php if(!$events):?><div class="empty-state"><h2>No events yet</h2><a class="button primary" href="create.php">Create your first event</a></div><?php endif?></section><?php app_footer();
